def is_coprime(a, b):
    while b != 0:
        a, b = b, a % b
    return a == 1

def count_minimal_coprimes(l, r):
    if l == r:
        return 1 if is_coprime(l, r) else 0

    count = 0
    for i in range(1, r + 1):
        if is_coprime(i, r):
            for j in range(i + 1, r + 1):
                if is_coprime(j, r) and not is_coprime(i, j):
                    count += 1
    return count

