def fix_expression(s):
    # Check if the expression is already true
    if s == "3<7" or s == "8>7" or s == "8<9" or s == "0=0":
        return s

    # Find the position of the comparison symbol
    i = s.index('<') if '<' in s else s.index('>') if '>' in s else s.index('=')

    # Swap the comparison symbol with the next digit
    if s[i] == '<':
        return f"{s[0]}{s[2]}{int(s[1]) + 1}"
    elif s[i] == '>':
        return f"{s[0]}{s[2]}{int(s[1]) - 1}"
    else:
        return f"{s[0]}{s[2]}{int(s[1])}"

