def is_stable(subset):
    # Check if the subset forms a non-degenerate triangle
    for i in range(len(subset)):
        for j in range(i + 1, len(subset)):
            for k in range(j + 1, len(subset)):
                if subset[i] + subset[j] <= subset[k]:
                    return False
    return True

def partition_is_possible(n, arr):
    # Generate all subsets of the array
    from itertools import chain, combinations

    subsets = list(chain.from_iterable(combinations(arr, r) for r in range(1, n + 1)))

    # Count the number of stable subsets
    stable_count = sum(is_stable(subset) for subset in subsets)

    # Return YES if there are at least two stable subsets, NO otherwise
    return "YES" if stable_count >= 2 else "NO"

