def min_length(s):
    # Count the frequency of each character in the string
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Find the maximum frequency of any character
    max_freq = max(freq.values())

    # Calculate the minimum length
    return len(s) - max_freq

