def max_fibonacci(arr):
    n = len(arr)
    if n < 3:
        return 0

    # Initialize the Fibonacci sequence with the first three elements
    fib = [arr[0], arr[1], arr[2]]

    # Calculate the next Fibonacci numbers up to the fourth element
    for i in range(3, n):
        fib.append(fib[i-1] + fib[i-2])

    # Check the number of consecutive Fibonacci numbers in the array
    count = 0
    for i in range(n-2):
        if fib[i] == fib[i+1] and fib[i+1] == fib[i+2]:
            count += 1

    return count

