    # Check if n is less than or equal to 1
    if n <= 1:
        return -1

    # Start checking from the smallest possible number with n digits
    for i in range(10**(n-1), 10**n):
        num_str = str(i)
        # Check if the number consists only of '3' and '6'
        if all(c in '36' for c in num_str):
            # Check if the number is divisible by 33 and 66
            if int(num_str) % 33 == 0 and int(num_str) % 66 == 0:
                return int(num_str)

    # If no valid number is found, return -1
    return -1

